import csv
import re
import io

data = """"Presidio Modelo (Panoptikon Hapishanesi)","Isla de la Juventud","Küba","Mahkumların her an izlendikleri paranoyasıyla aklını yitirdiği, dairesel mimariye sahip devasa ve çürüyen bu panoptikon hapishane. Binlerce esirin deliliğe sürüklendiği hücre bloklarının ortasında durduğunuzda, o ezici, kaotik izlenme korkusu ve kırık zihinlerin yarattığı ağır anksiyete frekansı auranızı tamamen felç eder.",5"La Cabaña Kalesi (İnfaz Duvarları)","Havana","Küba","Hem sömürge döneminde hem de devrim sonrasında sayısız muhalifin kurşuna dizildiği bu devasa taş kale. 'El Paredón' (İnfaz Duvarı) önünde gece yarısı durduğunuzda, havada asılı kalan o paslı barut kokusunu, son duayı edenlerin feryatlarını ve o ani, travmatik ölümün sarsıcı frekansını göğsünüzde hissedersiniz.",5"Manaca Iznaga (Kölelik Kulesi)","Trinidad","Küba","Şeker kamışı tarlalarında yüzlerce Afrikalı kölenin kırbaçlar altında can verdiği ve işkence gördüğü bu kanlı vadi. Kuleye tırmanırken toprağa sinmiş olan o devasa atalardan kalma kederi hisseder; geceleri Palo Mayombe ritüellerinin ve haksız yere ölen kölelerin o karanlık, intikamcı frekansının havada yankılandığına şahit olursunuz.",5"Cristóbal Colón Mezarlığı","Havana","Küba","Dünyanın en büyük ve en gotik anıt mezarlıklarından biri olan bu devasa nekropol. Geceleri karanlık çöktüğünde mermer lahitlerin arasında yapılan Santería ve kara büyü ritüellerinin (Palo) enerjisi uyanır; heykellerin boş gözlerinden size sızan o ağır ölüm frekansı ve karanlığın içindeki şekilsiz varlıklar zihninizi ürpertir.",4"El Morro Kalesi (Korsan Zindanları)","Santiago de Cuba","Küba","Karayip korsanlarının saldırılarına karşı inşa edilen ve altındaki zifiri karanlık zindanlarda mahkumların denizin yükselmesiyle diri diri boğulduğu bu kale. Suların taş duvarlara çarpma sesine karışan boğuk çığlıklar ve denizin o yutucu, acımasız karanlık enerjisi, ziyaretçileri boğucu bir klostrofobiye sürükler.",4"Hotel Nacional de Cuba","Havana","Küba","1930'larda Amerikan mafyasının kanlı toplantılarına ve şiddetli çatışmalara sahne olan bu ikonik ve lüks otel. Geceleri boş koridorlarda yankılanan silah sesleri ve eski balo salonunda beliren aristokratik gölgeler; ihanetin, kibrin ve şiddetin o ağır, eski zaman frekansının burada sonsuz bir döngüye kilitlendiğini kanıtlar.",4"San Lázaro Cüzzam Hastanesi","Havana","Küba","Asırlar boyunca cüzzam hastalarının ve salgın kurbanlarının toplumdan izole edilerek çürümeye terk edildiği bu tarihi kompleks. Terk edilmiş eski koğuşlardan gelen bedensiz iniltiler ve Babalú Ayé'ye (hastalık orishası) adanan adakların yarattığı o ağır, sülfürik hastalık frekansı auranızı fiziksel olarak yorar.",4"Cueva de los Portales","Pinar del Río","Küba","Soğuk Savaş paranoyasının zirvesinde askeri sığınak olarak kullanılan, ancak çok daha öncesinde yerli Taíno halkının şamanik ritüellerine ev sahipliği yapmış bu devasa mağara. Yeraltının o ilkel, ezici doğa enerjisiyle savaşın gergin frekansının çarpıştığı bu dehlizlerde ilerlerken, görünmez varlıkların sizi izlediğini hissedersiniz.",3"Casa de las Viudas (Dul Kadınlar Evi)","Camagüey","Küba","Kocaları korsan saldırılarında veya savaşlarda ölen kadınların ömür boyu yas tuttuğu bu eski sömürge dönemi malikanesi. Boş pencerelerden dışarı bakan siyahlı kadın silüetleri ve odalara sinmiş o bitmek bilmeyen, melankolik bekleyiş enerjisi; içeri adım atanların kalbine saf, devasa bir hüzün zerk eder.",4"Teatro Sauto","Matanzas","Küba","19. yüzyıldan kalma bu görkemli tiyatro, sahnede trajik bir şekilde can veren oyuncuların ve localarda cinayete kurban giden aristokratların ruhlarını barındırır. Seyircisiz salonda kendiliğinden açılan kadife perdeler ve aniden düşen dondurucu sıcaklık, buranın sanatın ve ölümün karanlık bir astral sahnesi olduğunu gösterir.",3"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Kuba kayitlari eklendi.")
